def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            ns=[g[y][x] for y,x in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=y<h and 0<=x<w]
            if g[i][j] not in ns:
                c=Counter(ns).most_common()
                if len(c)==1 or c[0][1]>c[1][1]:
